def _make_sparse_coo(shape, sparse_dim, nnz, dtype, device, seed=0, coalesced=True):
    g = torch.Generator(device="cpu").manual_seed(seed)
    idx = torch.stack(
        [torch.randint(0, s, (nnz,), generator=g) for s in shape[:sparse_dim]]
    ).to(device)
    values = torch.ones(
        (nnz,) + tuple(shape[sparse_dim:]), dtype=dtype, device=device
    )
    t = torch.sparse_coo_tensor(idx, values, shape, device=device, dtype=dtype)
    return t.coalesce() if coalesced else t


def _assert_sparse_close(res, ref, dtype):
    assert res.shape == ref.shape
    assert res.sparse_dim() == ref.sparse_dim()
    assert res.is_coalesced() == ref.is_coalesced()
    utils.gems_assert_equal(res._indices(), ref._indices())
    utils.gems_assert_close(res.to_dense(), ref.to_dense(), dtype)


