@pytest.mark.sparse_mask
def test_sparse_mask_does_not_mutate_inputs():
    self_t = torch.randn((16, 32), dtype=torch.float32, device=flag_gems.device)
    mask = _make_sparse_coo(
        (16, 32), 2, 40, torch.float32, flag_gems.device, seed=7
    )
    self_before = self_t.clone()
    mask_before = mask.clone()
    flag_gems.sparse_mask(self_t, mask)
    utils.gems_assert_equal(self_t, self_before)
    utils.gems_assert_equal(mask.to_dense(), mask_before.to_dense())
